const log = $input.first().json;
const processed = {
  timestamp:     log.timestamp || new Date().toISOString(),
  event_type:    log.event_type || log.EventType || 'unknown',
  source_ip:     log.source_ip || log.SourceIP || null,
  destination:   log.destination || log.DestHost || null,
  user:          log.user || log.username || null,
  failure_count: log.failure_count || null,
  protocol:      log.protocol || null,
  message:       log.message || log.raw || JSON.stringify(log)
};
const searchQuery = [processed.event_type, processed.source_ip, processed.message]
  .filter(Boolean).join(' ').substring(0, 300);
return [{ json: { processed, searchQuery, logJson: JSON.stringify(processed, null, 2) } }];

const { searchQuery, logJson } = $input.first().json;
let ragContext = '';
try {
  const reqBody = JSON.stringify({ text: searchQuery, n_results: 3 });
  const data = await new Promise((resolve, reject) => {
    const req = require('http').request({
      hostname: 'rag-service', port: 8001, path: '/query', method: 'POST',
      headers: { 'Content-Type': 'application/json', 'Content-Length': Buffer.byteLength(reqBody) }
    }, res => {
      let raw = ''; res.on('data', c => raw += c);
      res.on('end', () => { try { resolve(JSON.parse(raw)); } catch(e) { resolve({}); } });
    });
    req.on('error', reject); req.write(reqBody); req.end();
  });
  const docs = data?.documents || [];
  if (docs.length > 0) {
    ragContext = '\n\nNgữ cảnh từ cơ sở tri thức bảo mật:\n' + docs.filter(Boolean).join('\n---\n');
  }
} catch (_) {}
return [{ json: { ragContext, logJson } }];

const { ragContext = '', logJson } = $input.first().json;
const systemPrompt = `Bạn là chuyên gia phân tích SOC an ninh mạng.
Hãy phân tích log đầu vào và trả về CHỈ một JSON hợp lệ theo định dạng:
{
  "threat_detected": <bool>,
  "severity": "<none|low|medium|high|critical>",
  "confidence": <0-100>,
  "attack_type": "<MITRE tactic hoặc null>",
  "mitre_technique": "<T1xxx hoặc null>",
  "affected_assets": ["<IP hoặc user>"],
  "reason": "<một câu>",
  "recommended_action": "<block_ip|disable_account|escalate|monitor|none>"
}
Chỉ trả về đối tượng JSON, không markdown.`;
const llmBody = JSON.stringify({
  model: 'Qwen/Qwen2.5-14B-Instruct-AWQ',
  messages: [
    { role: 'system', content: systemPrompt },
    { role: 'user', content: 'Phân tích log sau:' + ragContext + '\n\n' + logJson }
  ],
  max_tokens: 512,
  temperature: 0.05,
  response_format: { type: 'json_object' }
});
return [{ json: { llmBody, logJson } }];

const { llmBody, logJson } = $input.first().json;
// Cập nhật hostname sang host ngrok sau khi chạy Colab (bỏ port/dùng 443 cho https)
const llmResponse = await new Promise((resolve, reject) => {
  const req = require('http').request({
    hostname: 'host.docker.internal', port: 8080,
    path: '/v1/chat/completions', method: 'POST',
    headers: { 'Content-Type': 'application/json', 'Content-Length': Buffer.byteLength(llmBody) }
  }, res => {
    let raw = ''; res.on('data', c => raw += c);
    res.on('end', () => { try { resolve(JSON.parse(raw)); } catch(e) { resolve({}); } });
  });
  req.on('error', reject); req.write(llmBody); req.end();
});
return [{ json: { llmResponse, logJson } }];

const { llmResponse, logJson } = $input.first().json;
let analysis;
try {
  const content = llmResponse.choices[0].message.content;
  analysis = typeof content === 'string' ? JSON.parse(content) : content;
} catch (e) {
  analysis = {
    threat_detected: false, severity: 'none', confidence: 0,
    attack_type: null, mitre_technique: null, affected_assets: [],
    reason: 'Lỗi phân tích: ' + e.message, recommended_action: 'monitor'
  };
}
return [{ json: { ...analysis, logJson, analyzed_at: new Date().toISOString() } }];

const d = $input.first().json;
const ALERT_URL = 'https://webhook.site/REPLACE-WITH-YOUR-ID';
try {
  const alertData = JSON.stringify({
    alert_type: 'SECURITY_THREAT',
    severity:   d.severity,
    confidence: d.confidence + '%',
    attack:     d.attack_type,
    mitre:      d.mitre_technique,
    action:     d.recommended_action,
    reason:     d.reason,
    assets:     d.affected_assets,
    timestamp:  d.analyzed_at
  });
  const urlObj = new URL(ALERT_URL);
  await new Promise((resolve, reject) => {
    const req = require('https').request({
      hostname: urlObj.hostname, port: 443,
      path: urlObj.pathname, method: 'POST',
      headers: { 'Content-Type': 'application/json', 'Content-Length': Buffer.byteLength(alertData) }
    }, res => { res.on('data', () => {}); res.on('end', resolve); });
    req.on('error', reject); req.write(alertData); req.end();
  });
} catch (_) {}
return [{ json: { status: 'alerted', ...d } }];

const d = $input.first().json;
console.log('[CLEAN]', d.analyzed_at, '| độ tin cậy:', d.confidence, '| lý do:', d.reason);
return [{ json: { status: 'clean', ...d } }];
